with feeders as (
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , REF_BILL_ID as RELATED_BILL_REFERENCE
        , CLAIMED_AMT as CLAIMED_AMOUNT
        , TOT_APP_AMTMOU as MOU_APPROVED_AMOUNT
        , DISCOUNT as DISCOUNT_AMOUNT
        , TOT_COPAY_AMT as CO_PAY_AMOUNT
        , AMT_FRM_PATIENT as PATIENT_PAID_AMOUNT
        , cast(null as varchar) as BILL_ADJUDICATED_BY_USER
        , cast(null as varchar) as BILL_ADJUDICATION_TIMESTAMP
        , 'BJAZ_HM_BILL_DETAIL' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_bill_detail') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , cast(null as varchar) as RELATED_BILL_REFERENCE
        , CLAIMED_AMT as CLAIMED_AMOUNT
        , cast(null as varchar) as MOU_APPROVED_AMOUNT
        , cast(null as varchar) as DISCOUNT_AMOUNT
        , cast(null as varchar) as CO_PAY_AMOUNT
        , cast(null as varchar) as PATIENT_PAID_AMOUNT
        , cast(null as varchar) as BILL_ADJUDICATED_BY_USER
        , cast(null as varchar) as BILL_ADJUDICATION_TIMESTAMP
        , 'BJAZ_HM_BILL_DETAIL_OCR' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_bill_detail_ocr') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , cast(null as varchar) as RELATED_BILL_REFERENCE
        , cast(null as varchar) as CLAIMED_AMOUNT
        , cast(null as varchar) as MOU_APPROVED_AMOUNT
        , cast(null as varchar) as DISCOUNT_AMOUNT
        , cast(null as varchar) as CO_PAY_AMOUNT
        , cast(null as varchar) as PATIENT_PAID_AMOUNT
        , UPDATED_BY as BILL_ADJUDICATED_BY_USER
        , UPDATED_ON as BILL_ADJUDICATION_TIMESTAMP
        , 'BJAZ_HM_GPA_BILL_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_gpa_bill_dtls') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
),

resolved as (
    select
        HUB_CLAIM_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then RELATED_BILL_REFERENCE end) as RELATED_BILL_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CLAIMED_AMOUNT end) as CLAIMED_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then MOU_APPROVED_AMOUNT end) as MOU_APPROVED_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DISCOUNT_AMOUNT end) as DISCOUNT_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CO_PAY_AMOUNT end) as CO_PAY_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PATIENT_PAID_AMOUNT end) as PATIENT_PAID_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_v2' then BILL_ADJUDICATED_BY_USER end) as BILL_ADJUDICATED_BY_USER,
        max(case when SOURCE_RUN = 'opus_health_v2' then BILL_ADJUDICATION_TIMESTAMP end) as BILL_ADJUDICATION_TIMESTAMP,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CLAIM_HK
),

hashed as (
    select
        *,
        case when RELATED_BILL_REFERENCE is not null or CLAIMED_AMOUNT is not null or MOU_APPROVED_AMOUNT is not null or DISCOUNT_AMOUNT is not null or CO_PAY_AMOUNT is not null or PATIENT_PAID_AMOUNT is not null or BILL_ADJUDICATED_BY_USER is not null or BILL_ADJUDICATION_TIMESTAMP is not null
                     then md5(upper(coalesce(cast(RELATED_BILL_REFERENCE as varchar), '') || '|' || coalesce(cast(CLAIMED_AMOUNT as varchar), '') || '|' || coalesce(cast(MOU_APPROVED_AMOUNT as varchar), '') || '|' || coalesce(cast(DISCOUNT_AMOUNT as varchar), '') || '|' || coalesce(cast(CO_PAY_AMOUNT as varchar), '') || '|' || coalesce(cast(PATIENT_PAID_AMOUNT as varchar), '') || '|' || coalesce(cast(BILL_ADJUDICATED_BY_USER as varchar), '') || '|' || coalesce(cast(BILL_ADJUDICATION_TIMESTAMP as varchar), '')))
                end as SAT_CLAIM_PROVIDER_BILLING_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_PROVIDER_BILLING_HASHDIFF is not null
